C:\Users\o-neo\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\pwsh.exe -NoProfile -Command "try { [Console]::OutputEncoding=[System.Text.Encoding]::UTF8 } catch {}
$now = Get-Date
$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
$principal = [Security.Principal.WindowsPrincipal]::new($identity)
[pscustomobject]@{
  CollectedAt = $now.ToString('o')
  User = $identity.Name
  IsAdministrator = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
} | Format-List

'CURRENT_PYTHON_PROCESSES'
$allProcesses = Get-CimInstance Win32_Process
$pythonProcesses = $allProcesses | Where-Object { $_.Name -match '^python(w)?\.exe$' }
$pythonProcesses | Select-Object ProcessId,ParentProcessId,Name,ExecutablePath,CreationDate,CommandLine | Format-List

'PYTHON_PARENT_CHAINS'
foreach ($pythonProcess in $pythonProcesses) {
  $cursor = $pythonProcess
  $depth = 0
  while ($null -ne $cursor -and $depth -lt 12) {
    [pscustomobject]@{
      RootPythonPid = $pythonProcess.ProcessId
      Depth = $depth
      ProcessId = $cursor.ProcessId
      ParentProcessId = $cursor.ParentProcessId
      Name = $cursor.Name
      ExecutablePath = $cursor.ExecutablePath
      CommandLine = $cursor.CommandLine
      CreationDate = $cursor.CreationDate
    } | Format-List
    $parentProcessIdValue = [uint32]$cursor.ParentProcessId
    $cursor = $allProcesses | Where-Object { $_.ProcessId -eq $parentProcessIdValue } | Select-Object -First 1
    $depth++
  }
}

'PYTHON_PROCESS_WINDOWS_AND_MODULES'
foreach ($pythonProcess in $pythonProcesses) {
  try {
    $liveProcess = Get-Process -Id $pythonProcess.ProcessId -ErrorAction Stop
    [pscustomobject]@{
      ProcessId = $liveProcess.Id
      MainWindowTitle = $liveProcess.MainWindowTitle
      StartTime = try { $liveProcess.StartTime.ToString('o') } catch { $null }
      Path = try { $liveProcess.Path } catch { \"INACCESSIBLE: $($_.Exception.Message)\" }
      ModuleCount = try { @($liveProcess.Modules).Count } catch { -1 }
    } | Format-List
    try {
      $liveProcess.Modules | Select-Object ModuleName,FileName,FileVersionInfo | Format-Table -AutoSize
    } catch {
      \"MODULES_INACCESSIBLE pid=$($pythonProcess.ProcessId): $($_.Exception.Message)\"
    }
  } catch {
    \"PROCESS_EXITED pid=$($pythonProcess.ProcessId): $($_.Exception.Message)\"
  }
}

'PATH_PYTHON_COMMANDS'
Get-Command python,python3,py -All -ErrorAction SilentlyContinue | Select-Object Name,CommandType,Source,Path,Version | Format-Table -AutoSize
where.exe python 2>&1
where.exe py 2>&1"

